/// 插件导出的命令清单（snake_case，与 #[tauri::command] 函数名一致）。
/// tauri_plugin::Builder 会为每个命令在 permissions/autogenerated/commands/ 下
/// 生成 allow-<name> / deny-<name> 权限（`_` 转 `-`）。
const COMMANDS: &[&str] = &[
    "optimizer_get_status",
    "optimizer_refresh",
    "optimizer_resolve",
    "optimizer_get_config",
    "optimizer_set_config",
    "api_request",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build()
}
